 static boolean allowFrame(ClientSession pc,byte[] packet){var c=NativeAreaMaterialAction.current.get();return c==null||!(c.nativeSourcePhysicalNpcOutput instanceof Output out)||out.receiver()==pc&&current(out);}
 static void inherit(NativeAreaMaterialAction.Context child,NativeAreaMaterialAction.Context parent){if(parent!=null){child.nativeSourcePhysicalNpcOutput=parent.nativeSourcePhysicalNpcOutput;child.nativeSourcePhysicalNpcCommit=parent.nativeSourcePhysicalNpcCommit;}}
