 static void output(Commit p,ClientSession pc,NativePlayerCommit.Binding binding,byte[] packet,String note,boolean reaction){
  var out=new Output(p,pc,binding,packet.clone(),reaction);if(!current(out))return;
  // Preserve the original owned publication boundary: source action/admission locks never cover receiver IO.
  NativeLightAction.deferScoped(()->{try{var c=new NativeAreaMaterialAction.Context(pc);var previous=c.nativeSourcePhysicalNpcOutput;c.nativeSourcePhysicalNpcOutput=out;try{NativeAreaMaterialAction.owned(c,()->{synchronized(pc){if(current(out))pc.nativeSelfOriginalSend(out.packet(),note);}});}finally{c.nativeSourcePhysicalNpcOutput=previous;}}catch(IOException|RuntimeException failure){failed(p.lifetime);}});
 }
